-- supabase/sql/exam_question_bank_neet_pg_set2.sql
--
-- Second curated question-bank batch for 'NEET PG' (see exam_patterns_neet_pg.sql for the exam's
-- structure, and exam_question_bank_neet_pg_set1.sql for the first batch -- same table/schema, no
-- migration needed). All-new questions, no overlap with Set 1.
--
-- Same format as Set 1: every row is format='mcq' with a single isCorrect:true option, matching
-- NEET PG's 100% single-best-response format. 16 chapters (8 Pre-/Para-Clinical Sciences, 4
-- Clinical Medicine and Allied, 2 Surgery and Allied, 2 Obstetrics/Gynaecology/Anesthesia) each get
-- 4 questions, covering classic, high-yield MBBS/board-style facts.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_pg.sql and
-- exam_question_bank_neet_pg_set1.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Anatomy
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'The sciatic nerve, the largest nerve in the human body, arises from which plexus?',
 '[{"text":"Cervical plexus","isCorrect":false},{"text":"Brachial plexus","isCorrect":false},{"text":"Lumbosacral (sacral) plexus","isCorrect":true},{"text":"Coccygeal plexus","isCorrect":false}]'::jsonb,
 null, 'The sciatic nerve arises from the lumbosacral plexus (L4-S3), making it the largest and longest nerve in the human body.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'easy', 'mcq',
 'The largest artery in the human body is the:',
 '[{"text":"Pulmonary artery","isCorrect":false},{"text":"Aorta","isCorrect":true},{"text":"Renal artery","isCorrect":false},{"text":"Carotid artery","isCorrect":false}]'::jsonb,
 null, 'The aorta, arising from the left ventricle, is the largest artery in the body, distributing oxygenated blood to the systemic circulation.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'Which cranial nerve is primarily responsible for the muscles of facial expression?',
 '[{"text":"Trigeminal nerve (CN V)","isCorrect":false},{"text":"Facial nerve (CN VII)","isCorrect":true},{"text":"Glossopharyngeal nerve (CN IX)","isCorrect":false},{"text":"Hypoglossal nerve (CN XII)","isCorrect":false}]'::jsonb,
 null, 'The facial nerve (CN VII) innervates the muscles of facial expression; its damage (as in Bell''s palsy) causes facial weakness or paralysis.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'hard', 'mcq',
 'The coronary sinus, which collects most of the heart''s venous blood, drains into which chamber?',
 '[{"text":"Left atrium","isCorrect":false},{"text":"Right atrium","isCorrect":true},{"text":"Left ventricle","isCorrect":false},{"text":"Right ventricle","isCorrect":false}]'::jsonb,
 null, 'The coronary sinus, which collects deoxygenated blood from the cardiac veins, drains directly into the right atrium.'),

